import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import {spawn,spawnSync} from "node:child_process";

const ROOT=process.cwd(), ARTIFACT=path.join(ROOT,"artifacts/browser-qa/touch-scroll-navigation-browser-qa.json");
const touch=fs.readFileSync(path.join(ROOT,"js/01-stage-v8-touch-lock.js"),"utf8");
function chrome(){ for(const name of ["google-chrome","google-chrome-stable","chromium","chromium-browser"]){ const hit=spawnSync("bash",["-lc",`command -v ${name}`],{encoding:"utf8"}); if(hit.status===0&&hit.stdout.trim()) return hit.stdout.trim(); } throw new Error("Headless Chrome/Chromium is required for Touch / Scroll / Navigation browser QA."); }
function json(url){ return new Promise((resolve,reject)=>{ const deadline=Date.now()+15000; (function poll(){ fetch(url).then(r=>r.json()).then(resolve).catch(error=>Date.now()>deadline?reject(error):setTimeout(poll,50)); })(); }); }
class Cdp{ constructor(url){ this.ws=new WebSocket(url); this.id=0; this.pending=new Map(); this.ready=new Promise((ok,bad)=>{this.ws.onopen=ok;this.ws.onerror=bad;}); this.ws.onmessage=e=>{const m=JSON.parse(String(e.data));if(m.id&&this.pending.has(m.id)){const p=this.pending.get(m.id);this.pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result||{});}}; } async send(method,params={}){await this.ready;const id=++this.id;return new Promise((ok,bad)=>this.pending.set(id,{resolve:ok,reject:bad})&&this.ws.send(JSON.stringify({id,method,params})));} async eval(expression){const r=await this.send("Runtime.evaluate",{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw new Error(r.exceptionDetails.text);return r.result?.value;} close(){try{this.ws.close();}catch(_){}} }
const fixture=`<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><style>#game-stage{width:360px;height:700px;overflow:hidden}#vertical{height:150px;overflow-y:auto}#horizontal{width:200px;overflow-x:auto;white-space:nowrap}#spacer{height:500px}#wide{display:inline-block;width:700px;height:40px}button{min-width:48px;min-height:44px}</style><div id="game-stage"><div id="vertical" data-scroll-owner="y"><button id="scrollButton">scroll target</button><div id="spacer"></div></div><div id="horizontal" data-scroll-owner="x"><button id="horizontalButton">horizontal target</button><span id="wide"></span></div><button id="tapButton">tap</button><nav><button id="bottomNav">bottom</button><button id="mapNav">map</button></nav></div><script>window.__clicks={scroll:0,horizontal:0,tap:0,bottom:0,map:0};for(const id of Object.keys(window.__clicks)){document.getElementById(id+"Button")?.addEventListener("click",()=>window.__clicks[id]++);}document.getElementById("bottomNav").addEventListener("click",()=>window.__clicks.bottom++);document.getElementById("mapNav").addEventListener("click",()=>window.__clicks.map++);</script><script>${touch}</script>`;
const gesture=(id,dx,dy)=>`(()=>{const n=document.getElementById(${JSON.stringify(id)}),r=n.getBoundingClientRect(),x=r.left+10,y=r.top+10,p=31;n.dispatchEvent(new PointerEvent("pointerdown",{bubbles:true,pointerType:"touch",pointerId:p,clientX:x,clientY:y}));n.dispatchEvent(new PointerEvent("pointermove",{bubbles:true,pointerType:"touch",pointerId:p,clientX:x+${dx},clientY:y+${dy}}));n.dispatchEvent(new PointerEvent("pointerup",{bubbles:true,pointerType:"touch",pointerId:p,clientX:x+${dx},clientY:y+${dy}}));n.click();return window.__clicks;})()`;
const file=path.join(os.tmpdir(),"four-symbols-touch-scroll-navigation-qa.html");
fs.mkdirSync(path.dirname(ARTIFACT),{recursive:true});fs.writeFileSync(file,fixture);
let proc,client;
try{
 const bin=chrome(),port=9700+Math.floor(Math.random()*200),profile=fs.mkdtempSync(path.join(os.tmpdir(),"touch-qa-"));proc=spawn(bin,["--headless=new","--no-sandbox","--disable-gpu",`--remote-debugging-port=${port}`,`--user-data-dir=${profile}`,"about:blank"],{stdio:"ignore"});const page=(await json(`http://127.0.0.1:${port}/json/list`)).find(x=>x.type==="page");client=new Cdp(page.webSocketDebuggerUrl);await client.send("Page.enable");await client.send("Page.navigate",{url:"file://"+file});await new Promise(r=>setTimeout(r,250));
 const scroll=await client.eval(gesture("scrollButton",0,12));assert.equal(scroll.scroll,0,"vertical scroll fired click");
 const horizontal=await client.eval(gesture("horizontalButton",12,0));assert.equal(horizontal.horizontal,0,"horizontal scroll fired click");
 const tap=await client.eval(gesture("tapButton",4,3));assert.equal(tap.tap,1,"tap under 10 CSS px did not click");
 const nav=await client.eval(`(()=>{bottomNav.click();mapNav.click();return {clicks:window.__clicks,hitboxes:[bottomNav,mapNav].map(n=>{const r=n.getBoundingClientRect();return r.width>=44&&r.height>=44;})}})()`);assert.deepEqual(nav.hitboxes,[true,true]);assert.equal(nav.clicks.bottom,1);assert.equal(nav.clicks.map,1);
 const evidence={suite:"touch-scroll-navigation-browser-qa",passed:true,checks:{scrollOver10DoesNotClick:true,tapUnder10Clicks:true,horizontalScrollDoesNotClick:true,navHitboxNoDeadZone:true,navigationOnce:true,lazyFirstTapFeedback:"covered by navigation intent static contract"}};fs.writeFileSync(ARTIFACT,JSON.stringify(evidence,null,2)+"\n");console.log("Touch / Scroll / Navigation browser QA passed.");
}catch(error){fs.writeFileSync(ARTIFACT,JSON.stringify({suite:"touch-scroll-navigation-browser-qa",passed:false,error:String(error?.stack||error)},null,2)+"\n");throw error;}finally{client?.close();proc?.kill("SIGTERM");try{fs.unlinkSync(file);}catch(_){}}
